<section class="panel"><div class="panel-head"><div><span class="panel-kicker">النشرة البريدية</span><h2>مشتركو البريد</h2></div><span><?=count($rows)?> سجل</span></div>
<div class="table-wrap"><table><thead><tr><th>البريد</th><th>اللغة</th><th>الحالة</th><th>تاريخ الاشتراك</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['email'])?></strong></td><td><?=e($r['locale'])?></td><td><span class="status <?=$r['status']==='active'?'s-active':'s-blocked'?>"><?=e($r['status'])?></span></td><td><?=e($r['created_at'])?></td><td><div class="inline-actions"><form method="post" action="/admin/newsletter/toggle"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-ghost"><?=$r['status']==='active'?'إلغاء الاشتراك':'إعادة التفعيل'?></button></form><form method="post" action="/admin/newsletter/delete" onsubmit="return confirm('حذف البريد نهائيًا؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
